escenas.animacion:
A.bg('#1d1a06', '#060504');
const enc = A.k('enciendes', 0.5), foco = A.k('foco', 0.9), casi = A.k('casi', 2.2), mueven = A.k('mueven', 3);
// interruptor
const on = t > enc;
A.rect(110, 620, 150, 240, { r: 24, fill: '#2b2f38', stroke: '#9aa3b2', lw: 5 });
A.rect(150, on ? 650 : 750, 70, 90, { r: 14, fill: on ? A.accent : '#5c6370', glow: on ? 30 : 0 });
// cable
const y = 900;
A.line([[260, 740], [330, 740], [330, y], [880, y], [880, 760]], { stroke: '#c46a2b', lw: 26 });
A.bulb(880, 620, { scale: 1.05, on: A.p(enc + 0.1, 0.25) });
// electrones casi quietos dentro del cable
A.particles(14, 3, (i, r) => {
  const x = 360 + i * 36 + Math.sin(t * 20 + i) * 2 + (t > enc ? (t - enc) * 4 : 0);
  A.circle(x, y + Math.sin(t * 15 + i * 2) * 3, 7, { fill: '#7fdcff', glow: 10 });
});
// lupa
const pl = A.pop(casi);
A.with(() => {
  A.circle(560, 1490, 190, { fill: '#0b1220', stroke: '#fff', lw: 12 });
  A.line([[695, 1625], [800, 1730]], { stroke: '#fff', lw: 26 });
  A.line([[380, 1490], [740, 1490]], { stroke: '#c46a2b', lw: 70, alpha: 0.6 });
  A.circle(560 + Math.sin(t * 25) * 5, 1490, 26, { fill: '#7fdcff', glow: 25 });
  A.text('e⁻', 560, 1430, { size: 44, color: '#7fdcff' });
}, { x: 560, y: 1490, scale: pl });
A.label('≈ 0.1 mm/s', 860, 1380, { scale: A.pop(mueven), size: 40 });

A.bg('#2a1306', '#080402');
const at = A.k('atomos', 0.6), cob = A.k('cobre', 1.8), ele = A.k('electrones', 2.4), lib = A.k('libres', 3.1), mov = A.k('moverse', 3.8);
const cols = 5, rows = 5, x0 = 220, y0 = 500, dx = 160, dy = 140;
for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
  const i = r * cols + c, s = A.pop(at + i * 0.03, 0.35);
  const x = x0 + c * dx, y = y0 + r * dy;
  A.circle(x, y, 46 * s, { fill: t > cob ? '#c46a2b' : '#5c6370', glow: t > cob ? 15 : 0, glowColor: '#ff9a4d' });
  A.text('+', x, y + 2, { size: 40 * s, color: '#fff', alpha: s });
  if (t > ele) { const a = t * 3 + i; A.circle(x + Math.cos(a) * 66, y + Math.sin(a) * 66, 9, { fill: '#7fdcff', alpha: A.p(ele, 0.3) }); }
}
// electrones libres que vagan entre los átomos
if (t > lib) A.particles(14, 11, (i, r) => {
  const bx = x0 - 60 + r() * 760, by = y0 - 40 + r() * 640, sp = 0.6 + r();
  const x = bx + Math.sin((t - lib) * sp * 2 + i) * 70 + (t > mov ? (t - mov) * 60 : 0) % 200;
  const y = by + Math.cos((t - lib) * sp * 1.7 + i * 2) * 50;
  A.circle(x, y, 12, { fill: '#7fdcff', glow: 25, alpha: A.p(lib, 0.4) });
});
A.label('COBRE', 540, 1400, { scale: A.pop(cob), size: 52, bg: '#c46a2b', color: '#fff' });
A.label('ELECTRONES LIBRES', 540, 1540, { scale: A.pop(lib), size: 44, bg: '#7fdcff' });

A.bg('#06202a', '#03080c');
const pila = A.k('pila', 0.4), bom = A.k('bomba', 1.4), pres = A.k('presion', 3), volt = A.k('voltaje', A.dur - 0.7);
// pila
const sp = A.pop(pila);
A.with(() => {
  A.rect(150, 560, 280, 460, { r: 30, fill: '#1f2937', stroke: '#fff', lw: 6 });
  A.rect(240, 520, 100, 50, { r: 10, fill: '#9aa3b2' });
  A.rect(150, 560, 280, 200, { r: 30, fill: A.accent });
  A.text('+', 290, 660, { size: 110, color: '#111' });
  A.text('−', 290, 900, { size: 110, color: '#fff' });
}, { x: 290, y: 790, scale: sp });
A.text('=', 540, 790, { size: 120, color: A.accent, alpha: A.p(bom, 0.3) });
// tanques de agua: diferencia de nivel
const pb = A.p(bom, 0.8);
const alto = A.lerp(0, 300, pb);
A.rect(640, 560, 150, 460, { r: 12, stroke: '#fff', lw: 5, alpha: A.p(bom, 0.3) });
A.rect(870, 560, 150, 460, { r: 12, stroke: '#fff', lw: 5, alpha: A.p(bom, 0.3) });
A.rect(645, 1015 - 150 - alto, 140, 150 + alto, { fill: '#2b8fd6', alpha: A.p(bom, 0.3) });
A.rect(875, 1015 - 150, 140, 150, { fill: '#2b8fd6', alpha: A.p(bom, 0.3) });
A.arrow(715, 1015 - 150 - alto + 20, 715, 960, { progress: A.p(pres, 0.5), color: '#fff', lw: 10 });
A.label('PRESIÓN', 830, 500, { scale: A.pop(pres), size: 40 });
// medidor de voltaje
const pv = A.p(volt - 0.2, 0.8, 'outElastic');
A.with(() => {
  ctx.save(); ctx.lineWidth = 26; ctx.strokeStyle = 'rgba(255,255,255,0.2)'; ctx.beginPath(); ctx.arc(540, 1640, 230, Math.PI, 2 * Math.PI); ctx.stroke();
  ctx.strokeStyle = A.accent; ctx.beginPath(); ctx.arc(540, 1640, 230, Math.PI, Math.PI + Math.PI * pv); ctx.stroke(); ctx.restore();
  const a = Math.PI + Math.PI * pv; A.line([[540, 1640], [540 + Math.cos(a) * 190, 1640 + Math.sin(a) * 190]], { stroke: '#fff', lw: 10 });
  A.circle(540, 1640, 22, { fill: '#fff' });
  A.text('VOLTAJE', 540, 1560, { size: 46 });
}, { alpha: A.p(pres + 0.4, 0.4) });

A.bg('#0a1f05', '#030602');
const cer = A.k('cerrar', 0.6), emp = A.k('empuja', 2), todos = A.k('todos', 2.6), corr = A.k('corriente', A.dur - 0.6);
const L = 140, R = 940, T = 500, B = 1080;
const path = [[L, T], [R, T], [R, B], [L, B], [L, T]];
A.line(path, { stroke: '#c46a2b', lw: 20 });
// pila a la izquierda
A.rect(L - 60, 700, 120, 180, { r: 16, fill: '#1f2937', stroke: '#fff', lw: 5 });
A.rect(L - 60, 700, 120, 70, { r: 16, fill: A.accent });
// interruptor arriba
const closed = A.p(cer, 0.3);
ctx.save(); ctx.fillStyle = '#060a04'; ctx.fillRect(440, T - 30, 200, 60); ctx.restore();
A.circle(450, T, 14, { fill: '#fff' }); A.circle(630, T, 14, { fill: '#fff' });
const ang = A.lerp(-0.6, 0, closed);
A.line([[450, T], [450 + Math.cos(ang) * 180, T + Math.sin(ang) * 180]], { stroke: '#fff', lw: 12 });
A.bulb(R, 790, { scale: 0.8, on: A.p(emp, 0.3) });
// electrones a lo largo del circuito
const per = 2 * (R - L) + 2 * (B - T), n = 26;
const avance = t > emp ? (t - emp) * 70 : 0;
function punto(d) {
  d = ((d % per) + per) % per;
  if (d < R - L) return [L + d, T]; d -= R - L;
  if (d < B - T) return [R, T + d]; d -= B - T;
  if (d < R - L) return [R - d, B]; d -= R - L;
  return [L, B - d];
}
for (let i = 0; i < n; i++) {
  const [x, y] = punto(i * per / n - avance);
  if (Math.abs(y - T) < 1 && x > 430 && x < 650) continue;
  A.circle(x, y, 11, { fill: '#7fdcff', glow: t > emp ? 25 : 0 });
}
A.label('¡TODOS A LA VEZ!', 540, 790, { scale: A.pop(todos), size: 44 });
A.label('CORRIENTE', 540, 1420, { scale: A.pop(corr), size: 56 });
for (let i = 0; i < 3; i++) A.arrow(300 + i * 180, 1560, 420 + i * 180, 1560, { progress: A.p(corr + 0.2 + i * 0.1, 0.3), color: '#7fdcff', lw: 10 });

A.bg('#2a1406', '#070302');
const horm = A.k('hormiga', 1.2), emp = A.k('empujon', 2.6), luz = A.k('luz', A.dur - 0.6);
// carril 1: hormiga vs electrón
A.text('HORMIGA', 120, 520, { size: 36, align: 'left', alpha: A.p(horm - 0.6, 0.3) });
A.line([[100, 640], [980, 640]], { stroke: 'rgba(255,255,255,0.3)', lw: 4 });
A.ant(200 + Math.max(0, t - (horm - 0.6)) * 70, 600, 1.2);
A.text('ELECTRÓN', 120, 740, { size: 36, align: 'left', alpha: A.p(horm - 0.6, 0.3) });
A.line([[100, 840], [980, 840]], { stroke: 'rgba(255,255,255,0.3)', lw: 4 });
A.circle(200 + Math.max(0, t - (horm - 0.6)) * 6, 810, 16, { fill: '#7fdcff', glow: 20 });
A.label('MÁS LENTO', 600, 790, { scale: A.pop(horm + 0.2), size: 36, bg: '#7fdcff' });
// cable: pulso de energía rapidísimo
A.line([[60, 1500], [1020, 1500]], { stroke: '#c46a2b', lw: 40, alpha: A.p(emp - 0.4, 0.3) });
if (t > emp) for (let i = 0; i < 6; i++) {
  const x = 60 + (((t - emp) * 2600 + i * 180) % 1200);
  if (x < 1020) A.rect(x - 90, 1480, 180, 40, { r: 20, fill: A.accent, glow: 50, alpha: 0.9 });
}
A.text('EMPUJÓN (ENERGÍA)', 540, 1400, { size: 40, alpha: A.p(emp, 0.3) });
A.label('≈ VELOCIDAD DE LA LUZ', 540, 1640, { scale: A.pop(luz), size: 44 });

A.bg('#06202a', '#03080c');
const fila = A.k('fila', 0.6), emp = A.k('empujas', 2), sale = A.k('sale', 3.2), otro = A.k('otro', A.dur - 0.8);
const n = 8, r = 48, y = 800, x0 = 170;
A.rect(110, y - 70, 840, 140, { r: 70, stroke: '#fff', lw: 6, fill: 'rgba(255,255,255,0.05)', alpha: A.p(fila - 0.4, 0.3) });
const push = A.p(emp + 0.2, 0.25, 'outCubic');
for (let i = 0; i < n; i++) {
  const s = A.pop(fila + i * 0.06, 0.3);
  let x = x0 + i * 2 * r + 40 + push * 2 * r, yy = y;
  if (i === n - 1 && push > 0) { const f = A.p(emp + 0.35, 0.8, 'inCubic'); x += f * 30; yy += f * 260; }
  A.circle(x, yy, r * 0.92 * s, { fill: i === 0 ? A.accent : '#e8e8e8', glow: i === 0 ? 20 : 0 });
}
// dedo/flecha que empuja
A.arrow(-60 + A.p(emp - 0.2, 0.4) * 130, y, 60 + A.p(emp - 0.2, 0.4) * 130, y, { progress: A.p(emp - 0.4, 0.3), color: '#fff', lw: 18, head: 50 });
A.label('EMPUJAS AQUÍ', 260, 620, { scale: A.pop(emp), size: 36 });
A.label('¡Y SALE ALLÁ!', 820, 1050, { scale: A.pop(sale), size: 40, bg: '#FFD400' });
A.text('igual que la energía en el cable', 540, 1500, { size: 42, weight: 600, alpha: A.p(otro, 0.4) });

A.bg('#1d1a06', '#060504');
const fil = A.k('filamento', 0.9), del = A.k('delgado', 2.2), cue = A.k('cuesta', 3.2), res = A.k('resistencia', 4.4), cal = A.k('calienta', 5.2), bri = A.k('brilla', A.dur - 0.6);
const heat = A.p(cal - 0.4, Math.max(bri - cal + 0.6, 0.3), 'linear');
// canal ancho -> filamento estrecho -> canal ancho
ctx.save(); ctx.fillStyle = '#c46a2b';
ctx.beginPath(); ctx.moveTo(60, 620); ctx.lineTo(380, 620); ctx.lineTo(420, 770); ctx.lineTo(660, 770); ctx.lineTo(700, 620); ctx.lineTo(1020, 620);
ctx.lineTo(1020, 960); ctx.lineTo(700, 960); ctx.lineTo(660, 810); ctx.lineTo(420, 810); ctx.lineTo(380, 960); ctx.lineTo(60, 960); ctx.closePath(); ctx.fill(); ctx.restore();
const col = `rgb(${Math.round(A.lerp(120, 255, heat))},${Math.round(A.lerp(40, 245, heat * heat))},${Math.round(A.lerp(20, 200, heat * heat * heat))})`;
A.rect(400, 765, 280, 50, { r: 10, fill: col, glow: 80 * heat, glowColor: '#ffcf6b' });
A.particles(30, 5, (i, r) => {
  const lane = r(), sp = 120 + r() * 60;
  let x = 60 + ((t * sp + i * 40) % 960), y;
  if (x < 380 || x > 700) y = 640 + lane * 300; else y = 775 + lane * 30;
  if (x > 380 && x < 700 && t > cue) x += Math.sin(t * 30 + i) * 6;
  A.circle(x, y, 9, { fill: '#7fdcff', alpha: A.p(fil - 0.3, 0.4) });
});
A.label('FILAMENTO', 540, 540, { scale: A.pop(fil), size: 40 });
A.label('MUY DELGADO', 540, 1050, { scale: A.pop(del), size: 36, bg: '#fff' });
A.label('RESISTENCIA', 540, 1400, { scale: A.pop(res), size: 52 });
A.text('≈ ' + A.counter(20, 2500, heat) + ' °C', 540, 1560, { size: 80, weight: 900, color: col, alpha: A.p(cal - 0.4, 0.3) });
A.flash(bri, 0.25, 0.4);

A.bg('#2a1406', '#070302');
const alt = A.k('alterna', 0.8), van = A.k('van', 1.6), cin = A.k('cincuenta', 2.6), ses = A.k('sesenta', 3.3), pais = A.k('paises', A.dur - 0.6);
const y = 780, f = t > van ? Math.sin((t - van) * 2 * Math.PI * 1.5) : 0;
A.line([[60, y], [1020, y]], { stroke: '#c46a2b', lw: 60 });
for (let i = 0; i < 12; i++) {
  const x = 110 + i * 80 + f * 30;
  A.circle(x, y, 12, { fill: '#7fdcff', glow: 18 });
}
A.arrow(420, 640, 300, 640, { progress: f < 0 ? 1 : 0, color: A.accent, lw: 12 });
A.arrow(660, 640, 780, 640, { progress: f > 0 ? 1 : 0, color: A.accent, lw: 12 });
A.label('CORRIENTE ALTERNA', 540, 520, { scale: A.pop(alt), size: 42 });
// onda senoidal
const pw = A.p(van, 1.5, 'linear');
const pts = []; for (let x = 120; x <= 120 + 840 * pw; x += 6) pts.push([x, 1560 + Math.sin((x - 120) / 840 * 2 * Math.PI * 3 - t * 4) * 110]);
if (pts.length > 1) A.line(pts, { stroke: A.accent, lw: 8, glow: 20 });
A.line([[120, 1560], [960, 1560]], { stroke: 'rgba(255,255,255,0.3)', lw: 3, alpha: A.p(van, 0.3) });
A.label('50 Hz', 330, 1400, { scale: A.pop(cin), size: 44, bg: '#fff' });
A.label('60 Hz', 750, 1400, { scale: A.pop(ses), size: 44 });
A.text('veces por segundo', 540, 1740, { size: 38, weight: 600, alpha: A.p(cin, 0.4) });

A.bg('#1c1806', '#050402');
const sig = A.k('siguenos', 0.2), mun = A.k('mundo', 1.8), apa = A.k('aparato', 3);
A.bulb(540, 700, { scale: 1.6, on: 0.6 + 0.4 * Math.abs(Math.sin(t * 2)) });
A.particles(10, 4, (i, r) => { const a = r() * Math.PI * 2 + t; A.circle(540 + Math.cos(a) * (280 + r() * 60), 700 + Math.sin(a) * (280 + r() * 60), 10, { fill: '#7fdcff', glow: 20 }); });
A.follow(540, 1425, sig + 0.1, mun - 0.3);
['¿MICROONDAS?', '¿WIFI?', '¿IMANES?'].forEach((q, i) => {
  const x = [250, 540, 830][i], y = 1640 + (i % 2) * 70 + Math.sin(t * 3 + i) * 8;
  A.label(q, x, y, { scale: A.pop(apa + i * 0.2), size: 32, bg: i === 1 ? '#fff' : A.accent });
});
